from collections import Counter
def transform(g):
    H,W=len(g),len(g[0])
    cnt=Counter(x for row in g for x in row if x)
    frame=max(cnt,key=lambda c:cnt[c])
    rest={c:cnt[c] for c in cnt if c!=frame}
    excl=max(rest,key=lambda c:rest[c])
    P={c:[(r,i) for r in range(H) for i in range(W) if g[r][i]==c] for c in rest if c!=excl}
    out=[row[:] for row in g]
    for c,ps in P.items():
        for a in ps:
            for b in ps:
                if a[0]==b[0] and a[1]<b[1]:
                    for j in range(a[1]+1,b[1]):
                        if out[a[0]][j]==0: out[a[0]][j]=c
